import AppKit
import ImageIO
import Carbon

enum ClipboardContent {
    static let excluded = ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
                           "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"]
    static let maxPixels = 16_777_216

    static func read(_ pasteboard: NSPasteboard) -> (String, Data)? {
        let types = Set(pasteboard.types?.map(\.rawValue) ?? [])
        guard !excluded.contains(where: types.contains), !types.contains(NSPasteboard.PasteboardType.fileURL.rawValue) else { return nil }
        for type in [NSPasteboard.PasteboardType.png, .tiff] where types.contains(type.rawValue) {
            guard let data = pasteboard.data(forType: type), data.count <= HistoryStore.maxItemBytes,
                  let png = normalizedImage(data) else { return nil }
            return ("image", png)
        }
        guard let value = pasteboard.string(forType: .string), !value.isEmpty else { return nil }
        let data = Data(value.utf8)
        return data.count <= HistoryStore.maxItemBytes ? ("text", data) : nil
    }

    static func normalizedImage(_ data: Data) -> Data? {
        guard let source = CGImageSourceCreateWithData(data as CFData, nil),
              let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any],
              let width = properties[kCGImagePropertyPixelWidth] as? Int,
              let height = properties[kCGImagePropertyPixelHeight] as? Int,
              width > 0, height > 0, width <= maxPixels / height,
              let image = CGImageSourceCreateImageAtIndex(source, 0, [kCGImageSourceShouldCache: false] as CFDictionary) else { return nil }
        let bitmap = NSBitmapImageRep(cgImage: image)
        guard let png = bitmap.representation(using: .png, properties: [:]), png.count <= HistoryStore.maxItemBytes else { return nil }
        return png
    }

    static func needsPreview(_ item: HistoryItem, width: CGFloat = 332) -> Bool {
        if item.kind == "image" { return true }
        let text = item.text
        return text.contains(where: { $0.isNewline || $0 == "\t" }) ||
            (text as NSString).size(withAttributes: [.font: NSFont.systemFont(ofSize: 14)]).width > width
    }
}

final class HotKey {
    private var ref: EventHotKeyRef?
    private var handler: EventHandlerRef?
    var onPress: (() -> Void)?

    init() {
        var type = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
        InstallEventHandler(GetApplicationEventTarget(), { _, _, context in
            guard let context else { return OSStatus(eventNotHandledErr) }
            Unmanaged<HotKey>.fromOpaque(context).takeUnretainedValue().onPress?()
            return noErr
        }, 1, &type, Unmanaged.passUnretained(self).toOpaque(), &handler)
    }

    func register(key: UInt32, modifiers: UInt32) -> Bool {
        var next: EventHotKeyRef?
        let result = RegisterEventHotKey(key, modifiers, EventHotKeyID(signature: 0x43434b50, id: 1), GetApplicationEventTarget(), 0, &next)
        guard result == noErr else { return false }
        if let ref { UnregisterEventHotKey(ref) }
        ref = next
        return true
    }

    deinit {
        if let ref { UnregisterEventHotKey(ref) }
        if let handler { RemoveEventHandler(handler) }
    }
}

enum PopupPlacement {
    static func frame(anchor: NSPoint, size: NSSize, screen: NSRect) -> NSRect {
        let width = min(size.width, screen.width)
        let height = min(size.height, screen.height)
        return NSRect(x: min(max(anchor.x + 10, screen.minX), screen.maxX - width),
                      y: min(max(anchor.y - height, screen.minY), screen.maxY - height), width: width, height: height)
    }
}
